def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    if n > 99:
        return 'C'

    op_c = 0
    for i in range(n):
        if history[i][1] == 'C':
            op_c += 1
    op_d = n - op_c

    if op_c == 0:
        return 'D'

    last_m = history[n - 1][0]
    last_o = history[n - 1][1]

    rec_len = 10 if n >= 10 else n
    rec_c = 0
    for i in range(n - rec_len, n):
        if history[i][1] == 'C':
            rec_c += 1
    f10 = rec_c / rec_len

    run = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == last_o:
            run += 1
        else:
            break

    d_c = 0
    d_d = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'C':
                d_c += 1
            else:
                d_d += 1

    overall = op_c / n

    if op_d == 0:
        if d_c >= 2 and f10 >= 0.9:
            return 'D'
        return 'C'

    if d_c >= 3 and d_c >= d_d and overall >= 0.5:
        return 'D'

    if last_o == 'D':
        if op_d * 2 >= n:
            return 'D'

        if run == 1:
            if (n >= 2 and history[n - 2][0] == 'D' and
                history[n - 2][1] == 'C' and overall >= 0.7):
                return 'C'
            if f10 >= 0.85 and overall >= 0.85 and rng.random() < 0.25:
                return 'C'
            return 'D'

        if run == 4 and last_m == 'D' and f10 >= 0.5:
            return 'C'

        return 'D'

    if op_d * 2 >= n:
        if run >= 5 and f10 >= 0.6:
            return 'C'
        return 'D'

    if n >= 95:
        if d_c >= 1 and f10 >= 0.65:
            return 'D'
        if f10 >= 0.85 and rng.random() < 0.12:
            return 'D'

    return 'C'
